from corpus_revision_authoring import add,Q

add('G3-EXP-V3-1','사는 곳과 움직이는 방법을 연결해요',
'''동물의 움직임을 살피면 몸의 특징과 생활하는 곳을 연결할 수 있습니다. 물속의 물고기는 지느러미와 몸을 움직여 헤엄치고, 많은 새는 날개를 움직여 납니다. 그러나 사는 곳 하나만으로 동물의 모든 움직임을 정할 수는 없습니다.
오리는 물에서 헤엄치지만 땅에서는 걷기도 합니다. 개구리도 땅에서 뛰고 물에서 헤엄칩니다. 한 동물이 두 가지 이상의 방법으로 이동할 수 있으므로, 물에서 본 모습과 땅에서 본 모습을 나누어 기록해야 합니다.
박쥐와 참새는 모두 날개로 날지만 같은 종류의 동물은 아닙니다. 이동 방법이 같다는 것은 비교한 특징 하나가 같다는 뜻입니다. 몸의 다른 특징까지 모두 같다는 결론은 따로 확인해야 합니다.
관찰표에는 동물 이름, 관찰한 장소, 실제 움직임을 적습니다. 오리가 물 위에 가만히 있는 장면만 보았다면 ‘관찰하는 동안 떠 있었다’고 씁니다. 그 기록을 ‘오리는 걸을 수 없다’로 바꾸면 보지 못한 능력까지 판단한 셈입니다.''',
'''세 동물을 묶는 활동에서도 기준을 먼저 정합니다. 지금 물에서 움직인 동물을 묶으면 오리와 물고기가 함께 들어갈 수 있습니다. 날개가 있는 동물을 묶으면 오리와 참새가 함께 들어갑니다. 대상이 바뀌지 않아도 분류 기준이 달라지면 묶음이 달라집니다.''',
'''한 장소에서 본 행동은 그 동물이 할 수 있는 행동 전체와 다를 수 있습니다. 여러 장소와 시간의 기록을 모으면 처음 기록의 빈 부분을 채울 수 있지만, 동물을 억지로 움직이게 하여 확인할 필요는 없습니다. 안전한 거리에서 관찰한 범위와 아직 확인하지 못한 범위를 구별해 설명합니다.''',
[Q('오리는 물과 땅에서 각각 어떻게 이동할 수 있나요?','물에서 헤엄치고 땅에서 걸을 수 있어요.',2,'땅에서는 걷기도'),Q('박쥐와 참새가 모두 난다는 사실로 무엇까지 말할 수 있나요?','이동 방법 하나가 같다고 말할 수 있어요.',3,'비교한 특징 하나'),Q('물에 떠 있는 오리만 보았다면 걷는 능력은 어떻게 판단해야 하나요?','그 관찰만으로 걷지 못한다고 판단할 수 없어요.',4,'관찰하는 동안 떠 있었다'),Q('사는 곳 하나로 모든 이동 방법을 정해도 되나요?','개구리와 오리처럼 여러 곳에서 다른 방법으로 이동하는 예가 있어요.',[1,2],'두 가지 이상의 방법')],
('수달이 물에서 헤엄치는 모습을 기록했습니다. 땅에서는 아직 관찰하지 않았습니다.','기록에 맞는 판단은 무엇인가요?',['관찰한 수달은 물에서 헤엄쳤다.','수달은 땅에서 절대 움직이지 못한다.','헤엄치는 동물은 모두 물고기다.','한 번 관찰했으니 모든 행동을 알았다.'],[2,4],'관찰한 사실의 범위를 지켜요.',['실제로 본 행동을 적었어요.','보지 않은 능력을 부정했어요.','특징 하나로 동물 종류를 같게 보았어요.','한 장면을 전체 행동으로 넓혔어요.']),[('이동','자리나 장소를 옮김'),('관찰 범위','실제로 살펴본 대상과 상황의 한계')],'서식지별 이동의 고정 분류와 없는 삽화 참조를 제거하고 복수 행동·분류 기준을 추가.')

add('G3-EXP-V3-2','빠르게 전하는 것과 정확히 전하는 것',
'''멀리 있는 사람에게 소식을 보내기 위해 사람들은 여러 통신 방법을 사용했습니다. 옛 봉수는 낮의 연기와 밤의 불빛 같은 신호로 정해진 소식을 전했습니다. 신호를 받을 수 있는 위치와 날씨 등이 중요했습니다.
편지는 내용을 글로 자세히 적을 수 있지만 물건처럼 실제로 운반해야 했습니다. 봉수의 정해진 신호와 편지의 긴 글은 담을 수 있는 정보가 달랐습니다. 어느 방법이 좋은지는 전달할 내용과 상황에 따라 판단해야 합니다.
오늘날 스마트폰으로 글과 사진을 빠르게 보낼 수 있습니다. 하지만 기기와 통신 연결이 필요하며, 연결이 끊기면 바로 전해지지 않을 수 있습니다. 빠른 전달이 언제 어디서나 반드시 이루어진다는 뜻은 아닙니다.
메시지가 빨리 도착했다고 그 내용까지 사실인 것은 아닙니다. 모르는 사람이 보낸 소식은 누가 어떤 근거로 썼는지 확인해야 합니다. 전달 속도와 내용의 정확성은 다른 기준입니다.''',
'''한 친구는 행사 시작 시간을 잘못 적은 메시지를 즉시 받았습니다. 다른 친구는 조금 늦게 도착한 안내에서 바른 시간을 확인했습니다. 첫 메시지는 속도에서는 빨랐지만 필요한 정보를 정확히 전달하지 못했습니다. 평가 기준을 나누면 장점과 부족한 점을 동시에 설명할 수 있습니다.''',
'''새로운 통신 방법이 생겼다고 이전 방법의 역할이 모두 사라지는 것은 아닙니다. 연결이 어려운 상황이나 기록을 남길 목적에 따라 다른 수단을 함께 쓸 수 있습니다. 발달을 설명할 때에는 바뀐 기능과 여전히 필요한 조건을 함께 살피고, ‘새것이므로 모든 기준에서 우수하다’는 결론은 피합니다.''',
[Q('봉수는 낮에 무엇으로 신호를 전했나요?','연기로 전했어요.',1,'낮의 연기'),Q('봉수와 편지는 담을 수 있는 정보가 어떻게 다른가요?','봉수는 정해진 신호를, 편지는 자세한 글을 전할 수 있어요.',[1,2],'글로 자세히'),Q('스마트폰 메시지가 바로 가지 않을 수 있는 경우는 무엇인가요?','통신 연결이 끊긴 경우예요.',3,'연결이 끊기면'),Q('먼저 도착한 소식을 더 정확하다고 판단해도 되나요?','도착 속도는 내용의 근거와 정확성을 보장하지 않아요.',4,'다른 기준')],
('가 안내는 즉시 도착했지만 시간을 잘못 적었습니다. 나 안내는 늦게 도착했지만 시간이 맞습니다.','기준에 맞는 평가는 무엇인가요?',['가는 빠르고 나는 시간 정보가 정확하다.','가는 빨라서 시간도 정확하다.','나는 늦어서 내용도 틀리다.','두 안내의 차이를 비교할 수 없다.'],[3,4],'속도와 정확성을 나누어 판단해요.',['서로 다른 기준을 구별했어요.','빠름을 정확함으로 바꾸었어요.','느림을 오류로 바꾸었어요.','주어진 비교 정보를 버렸어요.']),[('통신','멀리 있는 사람과 소식을 주고받음'),('정확성','내용이 사실이나 약속에 맞는 정도')],'언제 어디서나 즉시 전달된다는 과장을 연결 조건·정확성 판단으로 수정.')

add('G3-EXP-V3-3','흙이 만들어지는 두 과정을 이어요',
'''바위는 오랜 시간 동안 잘게 부서지거나 성질이 바뀔 수 있습니다. 물과 온도 변화, 생물의 활동 등이 이런 변화에 관련됩니다. 바위가 작은 알갱이로 변하는 과정은 흙이 만들어지는 과정의 일부입니다.
숲에서는 떨어진 잎과 죽은 생물의 일부가 작은 생물들의 작용으로 분해됩니다. 분해된 물질은 광물 알갱이와 섞여 흙의 성질에 영향을 줍니다. 따라서 흙을 돌가루 하나로만 설명하면 생물과 관련된 과정을 빠뜨리게 됩니다.
나무뿌리가 바위 틈에서 자라 틈을 넓히는 경우도 있습니다. 생물은 분해되는 재료가 되기도 하고 바위의 변화에 영향을 주기도 합니다. 두 설명은 서로를 부정하는 것이 아니라 흙이 만들어지는 여러 부분을 보여 줍니다.
흙은 장소에 따라 알갱이 크기와 포함된 물질이 다릅니다. 모래와 낙엽을 잠깐 섞었다고 숲의 흙과 모든 성질이 같아지는 것은 아닙니다. 만들어진 과정과 시간이 다르기 때문입니다.''',
'''자료 가는 바위가 작은 조각이 되는 모습을, 자료 나는 낙엽이 분해되는 모습을 담았습니다. 가에 낙엽 설명이 없다고 생물이 중요하지 않다고 읽어서는 안 됩니다. 자료마다 집중한 과정이 다르므로, 두 자료를 연결하면 한 자료만 읽었을 때 빠진 부분을 보완할 수 있습니다.''',
'''어느 흙에서 식물이 잘 자랐다는 기록이 있어도 흙 이름만으로 원인을 정할 수는 없습니다. 물을 준 양과 빛, 식물의 처음 상태도 비교해야 합니다. 흙의 성질을 설명하는 글과 특정 식물의 자람을 검증하는 실험은 관련되지만 같은 자료는 아닙니다. 설명에서 얻은 생각을 실험으로 확인할 때에는 새로운 조건을 정해야 합니다.''',
[Q('바위의 변화에 관련되는 요인 하나를 쓰세요.','물, 온도 변화, 생물의 활동 등이에요.',1,'물과 온도 변화'),Q('바위 변화와 낙엽 분해 설명은 어떤 관계인가요?','흙이 만들어지는 서로 다른 부분을 보완해요.',[1,2,3],'여러 부분을 보여'),Q('바위 변화만 다룬 자료에 낙엽이 없으면 낙엽은 흙과 무관한가요?','다루지 않은 것일 수 있으므로 무관하다고 할 수 없어요.',2,'생물과 관련된 과정을'),Q('모래와 잎을 섞자 숲의 흙이 완성되었다는 말은 타당한가요?','분해와 변화의 과정·시간이 같지 않아요.',4,'과정과 시간이 다르기')],
('자료 가는 바위 틈의 변화, 자료 나는 잎의 분해를 설명합니다.','두 자료를 활용하는 방법은 무엇인가요?',['흙의 형성에 기여하는 두 과정을 연결한다.','가가 맞으면 나는 반드시 틀리다.','가에 없는 과정은 세상에 없다.','두 자료의 첫 문장만 이어서 모든 흙이 같다고 한다.'],[1,2,3],'서로 다른 부분의 설명을 통합해요.',['보완 관계를 찾았어요.','다른 설명을 모순으로 보았어요.','생략을 부정으로 바꾸었어요.','과정의 차이와 성질 차이를 지웠어요.']),[('분해','큰 물질이 더 작은 물질로 바뀜'),('광물','바위와 흙을 이루는 자연 물질')],'한 가지 원인으로 흙을 설명하는 오류를 보완 자료 통합 과제로 전환.')

add('G3-EXP-W1','물질의 상태를 설명하는 글의 순서',
'''친구에게 얼음, 물, 수증기의 차이를 설명하는 글을 쓰려고 합니다. 먼저 독자가 알고 싶은 점을 정합니다. ‘어떤 상태인가’만 나열할지, ‘그릇이 바뀌면 어떻게 달라지는가’를 비교할지에 따라 필요한 예가 달라집니다.
일상에서 다루는 고체는 일정한 모양과 부피를 갖습니다. 액체는 담긴 그릇에 따라 모양이 바뀌지만 부피는 거의 일정합니다. 기체는 담긴 공간을 채우며 모양과 부피가 달라질 수 있습니다. 이 설명은 같은 조건에서 상태의 특징을 비교하는 데 쓰입니다.
글쓴이는 물을 컵에서 넓은 그릇으로 옮기는 예를 넣었습니다. 물의 높이와 모양이 달라져도 흘리지 않았다면 물의 양이 저절로 줄어든 것은 아닙니다. 높이 하나를 부피와 같게 읽지 않도록 설명을 보탭니다.
글의 끝에서는 ‘액체는 그릇에 따라 모양이 바뀐다’고 정리합니다. ‘모든 고체는 단단하다’처럼 앞에서 다루지 않은 성질을 새 결론으로 넣지는 않습니다. 설명한 특징과 예, 정리가 이어져야 합니다.''',
'''고무 지우개와 돌은 모두 고체이지만 단단한 정도는 다릅니다. 고체를 설명할 때에는 단단함만으로 분류하지 않습니다. 독자가 혼동할 만한 예를 하나 더 넣으면 개념의 기준이 분명해집니다. 다만 예가 많아져도 비교하는 기준이 흐려지면 설명의 목적을 놓칩니다.''',
'''얼음이 녹는 상황은 상태가 그대로인 물을 그릇에 옮기는 상황과 다릅니다. 두 예를 한꺼번에 쓰려면 무엇을 바꾸었는지 나누어 밝혀야 합니다. 독자가 모양 변화와 상태 변화를 같은 것으로 이해하지 않는지 확인하고, 필요한 연결 문장을 보완합니다. 글의 순서는 정해진 틀을 채우는 일이 아니라 독자의 이해를 돕는 선택입니다.''',
[Q('글을 쓰기 전에 무엇을 먼저 정하나요?','독자가 알고 싶은 점과 비교할 특징을 정해요.',1,'독자가 알고 싶은 점'),Q('물을 다른 그릇에 옮기는 예는 어떤 특징을 설명하나요?','액체의 모양은 그릇에 따라 달라지지만 부피는 거의 일정함을 설명해요.',[2,3],'물의 양이 저절로 줄어든'),Q('넓은 그릇에서 높이가 낮아지면 물이 줄었다고 할 수 있나요?','흘렸는지와 양을 확인해야 하며 높이만으로 판단할 수 없어요.',3,'높이 하나를 부피와'),Q('끝에 모든 고체가 단단하다고 써도 되는가요?','앞의 비교는 모양과 부피이며 단단함을 입증하지 않았어요.',[2,4],'앞에서 다루지 않은 성질')],
('친구가 좁은 컵의 물을 넓은 컵으로 모두 옮긴 뒤 물 높이가 낮아졌다고 적었습니다.','덧붙일 설명은 무엇인가요?',['모양과 높이가 변해도 옮긴 물의 양은 같을 수 있다.','높이가 낮으니 물은 반드시 사라졌다.','물은 고체로 변했다.','컵 색깔만 알면 물의 양을 안다.'],[2,3],'서로 다른 측정 특징을 구별해요.',['사례와 원리가 이어져요.','높이와 양을 동일시했어요.','모양과 상태를 혼동했어요.','관계없는 정보를 골랐어요.']),[('부피','물체가 차지하는 공간의 크기'),('정리','앞에서 설명한 핵심을 모아 나타냄')],'고체는 모두 단단하다는 정의를 고치고 계획·예·결론의 일치로 쓰기 목표를 강화.')

add('G3-EXP-W2','자료를 내 말로 바꾸어도 뜻은 지켜요',
'''우리 고장의 옛 성을 소개하려고 자료를 찾았습니다. 자료에는 ‘성벽을 견고하게 쌓아 외부의 공격에 대비했다’고 적혀 있습니다. 글쓴이는 어려운 말을 쉬운 말로 바꾸어 메모하려고 합니다.
‘견고하게’는 튼튼하게라는 뜻입니다. 따라서 ‘공격에 대비해 성벽을 튼튼하게 쌓았다’고 바꾸면 핵심 뜻을 지킬 수 있습니다. 하지만 ‘아주 큰 돌만 골라 쌓았다’고 바꾸면 원문에 없는 재료와 크기를 보탠 것입니다.
자료를 자기 말로 바꾸었다고 출처를 적지 않아도 되는 것은 아닙니다. 어떤 자료에서 가져온 내용인지 이름과 확인할 위치를 남겨야 독자가 다시 살펴볼 수 있습니다. 출처를 적는 일과 뜻을 정확히 옮기는 일은 둘 다 필요합니다.
메모에는 자료에서 확인한 내용과 내가 더 알아볼 질문을 나누어 적습니다. ‘튼튼하게 쌓았다’는 확인한 내용, ‘어떤 재료를 썼을까’는 질문입니다. 질문을 곧바로 사실처럼 소개문에 넣으면 독자가 확인된 정보로 오해할 수 있습니다.''',
'''두 자료가 성을 지은 시기를 다르게 적었다면 한쪽을 마음대로 지우지 않습니다. 건설을 시작한 때와 완성한 때를 각각 말하는지 먼저 확인합니다. 표현이 다른 이유를 찾은 뒤에도 해결되지 않으면 확인이 필요한 부분으로 남기고, 비교한 출처를 함께 기록합니다.''',
'''소개문을 쉽게 쓰려다 원문의 조건을 빼는 경우도 있습니다. ‘일부 성벽을 고쳤다’를 ‘성을 새로 지었다’로 바꾸면 범위와 행위가 모두 달라집니다. 어려운 낱말을 쉽게 바꾸는 일은 내용을 더 크게 만드는 일이 아닙니다. 원문과 메모를 나란히 놓고 대상, 행위, 조건이 같은지 확인합니다.''',
[Q('견고하게를 쉬운 말로 바꾸면 무엇인가요?','튼튼하게예요.',2,'튼튼하게라는 뜻'),Q('내 말로 쓴 메모에도 출처가 필요한 까닭은 무엇인가요?','독자가 어디서 온 정보인지 다시 확인할 수 있게 하기 위해서예요.',3,'다시 살펴볼 수'),Q('어떤 재료를 썼을까라는 질문을 소개문에 넣으려면 무엇을 해야 하나요?','재료를 알려 주는 자료를 더 찾아 확인해야 해요.',4,'내가 더 알아볼 질문'),Q('아주 큰 돌만 썼다는 메모는 원문에 충실한가요?','원문에 없는 재료와 크기를 더했으므로 충실하지 않아요.',[1,2],'원문에 없는 재료와 크기')],
('자료에는 ‘마을 사람들이 다리의 일부를 고쳤다’고 적혀 있습니다.','뜻을 지키는 메모는 무엇인가요?',['마을 사람들이 다리의 한 부분을 수리했다.','마을 사람들이 다리를 모두 새로 만들었다.','기계가 돌다리를 만들었다.','일부를 고쳤으니 출처는 없어도 된다.'],[2,3,4],'대상·행위·범위를 지켜 바꿔 써요.',['일부와 수리의 뜻을 유지했어요.','부분 수리를 전체 신축으로 바꿨어요.','주체와 재료를 새로 만들어 냈어요.','말 바꾸기와 출처 표기를 혼동했어요.']),[('출처','내용을 가져온 자료가 있는 곳'),('견고하다','튼튼하고 굳다')],'바꿔 쓰기만 하면 출처가 불필요하다는 오해와 원문에 없는 돌 재료 추론을 수정.')

add('G3-EXP-W3','자석 설명의 순서를 고쳐요',
'''민지는 자석을 처음 배우는 친구에게 설명하는 글을 준비했습니다. 모은 메모에는 ‘클립이 붙었다’, ‘나무 막대는 붙지 않았다’, ‘같은 극은 밀어냈다’, ‘내 필통은 빨간색이다’가 있습니다. 모든 메모를 그대로 넣기 전에 글의 목적과 관계있는지 골라야 합니다.
먼저 어떤 물체가 자석에 붙는지 설명하고, 다음으로 자석끼리의 관계를 설명하기로 했습니다. 클립과 나무 막대의 결과는 첫 부분에, 같은 극을 마주 댄 결과는 다음 부분에 넣으면 비교 기준이 분명해집니다.
‘클립이 붙었으니 금속은 모두 붙는다’는 문장은 고쳐야 합니다. 철처럼 잘 붙는 물질이 있지만 모든 금속이 같은 것은 아닙니다. 관찰한 물체의 이름과 결과를 정확히 쓰고, 관찰하지 않은 전체로 결론을 넓히지 않습니다.
필통 색은 이번 설명의 기준과 관계가 없어 뺐습니다. 끝에는 앞에서 확인한 성질을 짧게 정리합니다. 이 순서는 독자를 돕기 위한 한 가지 방법이며, 모든 설명문이 반드시 똑같은 순서여야 하는 것은 아닙니다.''',
'''친구는 자석끼리의 관계를 먼저 설명해도 이해할 수 있다고 했습니다. 순서를 바꾸더라도 서로 비교하는 메모를 가까이 두고 연결 말을 보태면 글이 이어질 수 있습니다. 좋은 개요인지 판단할 때에는 첫째·둘째라는 번호만 보지 말고 정보가 어떻게 묶였는지 확인합니다.''',
'''한 메모에 시험 방법이 빠져 있다면 위치를 옮기는 것만으로 부족함이 해결되지 않습니다. 어떤 자석과 물체를 어떻게 가까이했는지 다시 기록해야 합니다. 개요 수정은 정보의 배치를 고치는 일이고, 자료 보완은 부족한 내용을 채우는 일입니다. 둘 중 무엇이 필요한지 구별하면 고쳐 쓰기의 이유를 설명할 수 있습니다.''',
[Q('첫 부분에 함께 넣을 두 관찰은 무엇인가요?','클립이 붙고 나무 막대가 붙지 않은 관찰이에요.',2,'첫 부분에'),Q('같은 극의 결과를 다른 부분에 묶은 까닭은 무엇인가요?','물체가 붙는지와 자석끼리의 관계는 비교 기준이 다르기 때문이에요.',2,'비교 기준이 분명'),Q('필통이 빨갛다는 메모를 뺀 까닭은 무엇인가요?','이번 글의 자석 성질 설명과 관계없기 때문이에요.',[1,4],'설명의 기준과 관계'),Q('클립 하나가 붙은 결과는 모든 금속이 붙는다는 근거인가요?','물체 하나의 결과로 모든 금속을 판단할 수 없어요.',3,'모든 금속이 같은 것은')],
('메모 가는 철못이 붙은 결과, 나는 종이가 붙지 않은 결과, 다는 서로 다른 극이 끌어당긴 결과입니다.','같은 기준끼리 묶은 구성은 무엇인가요?',['가·나를 물체 반응으로, 다를 자석끼리 관계로 묶는다.','가·다를 글자 수가 같아서 묶는다.','나를 빼고 모든 물체가 붙는다고 쓴다.','셋의 순서만 바꾸면 관찰 조건은 필요 없다.'],[2,3],'정보가 다루는 관계로 묶어요.',['비교 기준이 일관돼요.','겉모양만으로 묶었어요.','반대 근거를 지웠어요.','배치와 내용의 충분함을 혼동했어요.']),[('개요','글에 넣을 내용과 순서를 간추린 계획'),('기준','비교하거나 나눌 때 쓰는 바탕')],'고정 서론본론결론 암기를 정보 묶기·자료 보완·과잉 일반화 점검으로 전환.')

add('G3-EXP-W4','고장의 생활을 설명할 때 조심할 말',
'''산이 많은 고장과 바다 가까운 고장의 생활을 비교하는 글을 씁니다. 산에서는 임산물을 얻거나 산의 경치를 활용하는 일이, 바닷가에서는 수산물을 얻거나 해변을 찾는 사람을 맞는 일이 나타날 수 있습니다. 자연환경은 생활과 관계가 있습니다.
그러나 산에 산다고 모든 사람이 나무를 기르는 것은 아니며, 바닷가에 산다고 모두 고기를 잡는 것도 아닙니다. 학교와 가게, 병원 등 여러 일터가 있고 교통이나 시설도 생활에 영향을 줍니다. 대표적인 예를 그 고장 사람 전체의 모습으로 바꾸면 부정확해집니다.
두 고장의 자료를 비교하려면 같은 질문을 사용합니다. 가 고장에서는 일자리, 나 고장에서는 집의 색만 조사했다면 생활의 공통점과 차이점을 충분히 비교하기 어렵습니다. 각 자료가 무엇을 보여 주는지 먼저 살핍니다.
소개문에는 ‘바닷가에서는 어업이 이루어지기도 한다’처럼 자료가 보여 주는 범위를 맞추어 씁니다. 고장 사진 한 장에 보이지 않는 직업이 없다고 단정하지 않습니다. 더 알고 싶은 생활 모습은 추가 자료에서 확인합니다.''',
'''한 바닷가 마을에는 항구와 시장이 함께 있고, 다른 바닷가 마을에는 해변을 찾는 관광객을 위한 시설이 많습니다. 바다라는 공통 조건이 있어도 생활 모습이 완전히 같지는 않습니다. 자연환경 외에 교통, 시설, 사람들이 해 온 선택을 함께 살피면 차이를 설명하는 데 도움이 됩니다.''',
'''비교 글에서 두 고장의 차이만 찾으면 사람들에게 공통으로 필요한 학교나 생활 시설을 놓칠 수 있습니다. 반대로 공통점만 쓰면 환경과 관련된 특징이 흐려집니다. 독자가 고장의 다양한 모습을 이해하게 하려면 공통점과 차이점, 자료로 확인하지 못한 부분을 구별하여 구성합니다.''',
[Q('고장의 생활에 영향을 주는 자연환경 외의 요인을 쓰세요.','교통이나 시설 등이에요.',2,'교통이나 시설'),Q('두 고장에서 같은 질문으로 조사할 까닭은 무엇인가요?','같은 기준으로 공통점과 차이점을 비교하기 위해서예요.',3,'같은 질문'),Q('바닷가 사진에 배만 보이면 가게에서 일하는 사람은 없다고 할 수 있나요?','사진에 보이지 않는 생활도 있을 수 있어요.',4,'사진 한 장에 보이지 않는'),Q('바닷가 사람은 모두 어부라는 문장은 적절한가요?','대표적인 예를 전체 사람으로 넓혀 부정확해요.',2,'모두 고기를 잡는 것도')],
('한 산골 마을 조사에서 임업, 가게, 숙박업에 종사하는 사람들이 확인되었습니다.','소개문에 알맞은 문장은 무엇인가요?',['산을 활용하는 일과 다른 여러 일이 함께 나타난다.','산골 사람은 모두 나무만 기른다.','가게가 있으므로 산의 영향은 전혀 없다.','한 마을 자료로 모든 산골의 직업 비율을 안다.'],[1,2,4],'환경의 영향과 생활의 다양성을 함께 설명해요.',['자료의 여러 모습을 반영했어요.','다른 직업을 삭제했어요.','다양성을 환경 영향 없음으로 바꿨어요.','조사 범위를 넘어 비율까지 단정했어요.']),[('임산물','산에서 얻는 나무·버섯 등의 생산물'),('어업','물고기 등 수산물을 얻는 일')],'환경 결정론과 직업 고정관념을 없애고 비교 기준과 대표성 판단을 보강.')

add('G3-EXP-W5','강낭콩 관찰 보고서를 다듬어요',
'''다음은 연습을 위해 만든 한 강낭콩의 관찰 기록입니다. 5월 2일 줄기 높이는 4센티미터, 5월 5일에는 7센티미터였습니다. 두 날 모두 흙 표면에서 줄기 끝까지 같은 자로 재었습니다. 중간 날의 높이는 기록하지 않았습니다.
초안에는 ‘강낭콩은 매일 1센티미터씩 자랐다’고 적었습니다. 두 기록 사이에 3센티미터 자란 것은 알 수 있지만, 날마다 똑같이 자랐는지는 알 수 없습니다. 측정하지 않은 날의 변화를 사실처럼 채워 넣으면 안 됩니다.
다른 문장에는 ‘물을 많이 주어서 빨리 자랐다’고 적었습니다. 그러나 비교할 다른 식물이나 물의 양 기록이 없습니다. 이번 기록만으로 자란 원인을 물의 양 하나로 정하기는 어렵습니다. 관찰한 변화와 원인에 대한 생각을 나누어 써야 합니다.
수정한 문장은 ‘같은 방법으로 잰 이 강낭콩의 높이가 5월 2일부터 5일까지 3센티미터 늘었다’입니다. 날짜, 대상, 단위, 측정 방법을 남기면 독자가 어떤 기록에서 결론을 냈는지 확인하기 쉽습니다. 맞춤법 점검과 함께 내용이 근거에 맞는지도 고칩니다.''',
'''친구는 5월 5일에 잎 끝까지 재었는데 처음에는 줄기 끝까지 쟀습니다. 숫자가 정밀하게 적혀 있어도 기준점이 달라졌다면 같은 변화량으로 비교하기 어렵습니다. 보고서를 다시 읽다가 이런 차이를 발견하면 수치를 예쁘게 꾸미기보다 측정 방법의 차이를 밝혀야 합니다.''',
'''다음 관찰에서는 날마다 같은 시각에 같은 부분을 재고 물을 준 양도 기록할 수 있습니다. 기록을 늘리면 새 질문에 답할 단서가 생기지만, 그 계획이 이미 지난날의 빈 기록을 채워 주지는 않습니다. 이번에 확인한 사실과 다음에 확인할 계획을 구별하면 보고서의 결론이 더 정확해집니다.''',
[Q('두 측정일 사이에 높이가 얼마나 늘었나요?','7에서 4를 빼면 3센티미터예요.',1,'4센티미터, 5월 5일에는 7센티미터'),Q('두 날 같은 부분을 잰 까닭은 무엇인가요?','같은 기준으로 높이 변화를 비교하기 위해서예요.',[1,4],'같은 방법으로'),Q('중간 날의 정확한 높이를 이 기록으로 알 수 있나요?','중간 날은 재지 않아 정확히 알 수 없어요.',[1,2],'날마다 똑같이 자랐는지는'),Q('물을 많이 준 것이 원인이라고 결론 내려도 되나요?','물의 양 기록과 비교 자료가 없어 원인을 확정할 수 없어요.',3,'비교할 다른 식물이나')],
('6월 1일 높이 5센티미터, 6월 4일 높이 11센티미터입니다. 같은 방법으로 재었지만 중간 기록은 없습니다.','근거에 맞는 결론은 무엇인가요?',['두 측정일 사이에 높이가 6센티미터 늘었다.','매일 정확히 2센티미터씩 자랐다.','물을 많이 주어서 자란 것이 증명되었다.','모든 강낭콩은 같은 속도로 자란다.'],[1,2,3,4],'전체 변화와 날짜별 변화·원인·전체 일반화를 구별해요.',['두 실제 기록의 차이를 사용했어요.','기록 없는 날의 값을 만들어 냈어요.','비교 없는 원인을 단정했어요.','한 식물을 전체 식물로 넓혔어요.']),[('초안','처음 써 놓은 글'),('측정 방법','무엇을 어떤 기준과 도구로 재었는지 정한 방식')],'단순 맞춤법 퇴고에서 관찰 간격·측정 기준·원인 결론의 타당성 점검으로 확장.')
